local IconCache={}
local function builtinIcon(name)
    if name=="characters" then name="chapters" end
    if not IconPNG[name] then return nil end
    if IconCache[name] then return IconCache[name] end
    local asset=getcustomasset or getsynasset
    if type(asset)~="function" or type(writefile)~="function" then return nil end
    local ok,result=pcall(function()
        local path="Nocturne_Icon_v17_"..name..".png"
        writefile(path,IconPNG[name])
        return asset(path)
    end)
    if ok then IconCache[name]=result return result end
    warn("[Nocturne icon] "..tostring(result))
    return nil
end

local UtilityCache={}
local function utilityIcon(name)
    local bytes=UtilityPNG[name]
    if not bytes then return nil end
    if UtilityCache[name] then return UtilityCache[name] end
    local asset=getcustomasset or getsynasset
    if type(asset)~="function" or type(writefile)~="function" then return nil end
    local ok,result=pcall(function()
        local path="Nocturne_Utility_v112_"..name
        writefile(path,bytes)
        return asset(path)
    end)
    if ok then UtilityCache[name]=result return result end
    warn("[Nocturne utility icon] "..tostring(result))
    return nil
end

local Images = {}
local function imageAsset(name)
    if Images[name]~=nil then return Images[name] or nil end
    local asset=getcustomasset or getsynasset
    if type(asset)~="function" or type(writefile)~="function" then Images[name]=false return nil end
    local ok,result=pcall(function()
        local path="Nocturne_Image_"..name
        if type(isfile)~="function" or not isfile(path) then
            local bytes=game:HttpGet("https://raw.githubusercontent.com/sametexe001/images/main/"..name)
            assert(bytes:sub(1,8)==string.char(137,80,78,71,13,10,26,10),"Invalid PNG")
            writefile(path,bytes)
        end
        return asset(path)
    end)
    Images[name]=ok and result or false
    if not ok then warn("[Nocturne image] "..name..": "..tostring(result)) end
    return ok and result or nil
end
local Faces = {}
local SMALL_FONT_BASE64 = [[]]
local BASE64_ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local BASE64_VALUES = {}
for index=1,#BASE64_ALPHABET do BASE64_VALUES[BASE64_ALPHABET:sub(index,index)]=index-1 end
local function decodeBase64(data)
    data=data:gsub("%s","")
    local output={}
    for index=1,#data,4 do
        local a=BASE64_VALUES[data:sub(index,index)]
        local b=BASE64_VALUES[data:sub(index+1,index+1)]
        local third=data:sub(index+2,index+2)
        local fourth=data:sub(index+3,index+3)
        if a==nil or b==nil then return nil end
        local c=BASE64_VALUES[third] or 0
        local d=BASE64_VALUES[fourth] or 0
        local packed=a*262144+b*4096+c*64+d
        table.insert(output,string.char(math.floor(packed/65536)%256))
        if third~="=" and third~="" then table.insert(output,string.char(math.floor(packed/256)%256)) end
        if fourth~="=" and fourth~="" then table.insert(output,string.char(packed%256)) end
    end
    return table.concat(output)
end
local function loadFonts()
    if Faces.Attempted then return end
    Faces.Attempted=true
    Faces.Families={}
    local asset=getcustomasset or getsynasset
    if type(asset)~="function" or type(writefile)~="function" then
        warn("[Nocturne] Custom fonts require getcustomasset and writefile; using fallback font") return
    end
    local smallOk,smallResult=pcall(function()
        local path="Nocturne_SmallFonts"
        if type(isfile)~="function" or not isfile(path..".ttf") then
            local bytes=assert(decodeBase64(SMALL_FONT_BASE64),"Invalid embedded Small Fonts data")
            assert(#bytes>100 and (bytes:sub(1,4)==string.char(0,1,0,0) or bytes:sub(1,4)=="OTTO"),"Invalid embedded Small Fonts file")
            writefile(path..".ttf",bytes)
        end
        local fontAsset=asset(path..".ttf")
        writefile(path..".json",Http:JSONEncode({name="Nocturne Small Fonts",faces={
            {name="Regular",weight=400,style="normal",assetId=fontAsset},
            {name="Bold",weight=700,style="normal",assetId=fontAsset},
        }}))
        local family=asset(path..".json")
        Faces.Families["Small Fonts"]={
            Regular=Font.new(family,Enum.FontWeight.Regular,Enum.FontStyle.Normal),
            Bold=Font.new(family,Enum.FontWeight.Bold,Enum.FontStyle.Normal),
        }
    end)
    if not smallOk then warn("[Nocturne Small Fonts] "..tostring(smallResult)) end
    local tahomaOk,tahomaResult=pcall(function()
        local sources={
            Regular={File="Nocturne_TahomaXP_Regular.ttf",Url="https://raw.githubusercontent.com/aap27781-commits/hhhh/main/fs-tahoma-8px%281%29.ttf"},
            Bold={File="Nocturne_TahomaXP_Bold.ttf",Url="https://github.com/sametexe001/luas/raw/refs/heads/main/fonts/TAHOMA-8PT-BOLD-WINDOWS-XP.TTF"},
        }
        local assets={}
        for name,source in pairs(sources) do
            if type(isfile)~="function" or not isfile(source.File) then
                local bytes=game:HttpGet(source.Url)
                assert(#bytes>100 and (bytes:sub(1,4)==string.char(0,1,0,0) or bytes:sub(1,4)=="OTTO"),"Invalid Tahoma XP "..name)
                writefile(source.File,bytes)
            end
            assets[name]=asset(source.File)
        end
        local path="Nocturne_TahomaXP.json"
        writefile(path,Http:JSONEncode({name="Nocturne Tahoma XP",faces={
            {name="Regular",weight=400,style="normal",assetId=assets.Regular},
            {name="Bold",weight=700,style="normal",assetId=assets.Bold},
        }}))
        local family=asset(path)
        Faces.Families["Tahoma XP"]={
            Regular=Font.new(family,Enum.FontWeight.Regular,Enum.FontStyle.Normal),
            Bold=Font.new(family,Enum.FontWeight.Bold,Enum.FontStyle.Normal),
        }
    end)
    if not tahomaOk then warn("[Nocturne Tahoma XP] "..tostring(tahomaResult)) end
end
local function selectFont(name)
    local requested=name=="Small Fonts" and "Small Fonts" or "Tahoma XP"
    local family=Faces.Families and Faces.Families[requested]
    if not family and Faces.Families then
        requested=Faces.Families["Small Fonts"] and "Small Fonts" or "Tahoma XP"
        family=Faces.Families[requested]
    end
    Faces.Regular=family and family.Regular or nil
    Faces.Bold=family and family.Bold or nil
    return family and requested or "Fallback"
end

-- Separate transparent glyph layers: black offset copy below the foreground.
-- The host retains its Text for automatic sizing, input, and public API updates.
local function addTextShadow(host)
    local shadow=Instance.new("TextLabel")
    local front=Instance.new("TextLabel")
    shadow.Name="NocturneTextShadow" front.Name="NocturneTextFace"
    for _,layer in ipairs({shadow,front}) do
        layer.BackgroundTransparency=1 layer.BorderSizePixel=0
        layer.Active=false layer.Selectable=false
        layer.TextStrokeTransparency=1
        layer.Size=UDim2.fromScale(1,1)
        layer.Parent=host
    end
    shadow.Position=UDim2.fromOffset(1,1)
    front.Position=UDim2.fromOffset(0,0)
    -- Store the intended opacity separately. The host is deliberately hidden
    -- while the shadow layers draw its text.
    local transparency=host.TextTransparency
    local updating=false
    local focused=false
    local connections={}
    local copy={"Text","FontFace","TextSize","TextScaled","TextWrapped","TextXAlignment","TextYAlignment","TextTruncate","LineHeight","MaxVisibleGraphemes"}
    local function sync()
        if updating then return end
        updating=true
        for _,property in ipairs(copy) do
            shadow[property]=host[property] front[property]=host[property]
        end
        -- Strip rich color tags from the shadow so it remains entirely black.
        shadow.RichText=false
        if host.RichText then
            local plain=host.Text:gsub("<br%s*/?>","\n")
            plain=plain:gsub("<[^>]->","")
            plain=plain:gsub("&lt;","<")
            plain=plain:gsub("&gt;",">")
            plain=plain:gsub("&amp;","&")
            shadow.Text=plain
        end
        front.RichText=host.RichText
        shadow.TextColor3=Color3.new(0,0,0)
        front.TextColor3=host.TextColor3
        shadow.TextTransparency=transparency
        front.TextTransparency=transparency
        shadow.ZIndex=host.ZIndex+1 front.ZIndex=host.ZIndex+2
        front.Visible=not focused
        host.TextStrokeTransparency=1
        host.TextTransparency=focused and transparency or 1
        updating=false
    end
    local function connect(signal,fn) table.insert(connections,signal:Connect(fn)) end
    for _,property in ipairs(copy) do connect(host:GetPropertyChangedSignal(property),sync) end
    for _,property in ipairs({"RichText","TextColor3","ZIndex"}) do connect(host:GetPropertyChangedSignal(property),sync) end
    if host:IsA("TextBox") then
        connect(host.Focused,function() focused=true sync() end)
        connect(host.FocusLost,function() focused=false sync() end)
    end
    connect(host.Destroying,function()
        for _,connection in ipairs(connections) do connection:Disconnect() end
    end)
    sync()
end

local function make(class, props, parent)
    local object = Instance.new(class)
    for key, value in pairs(props or {}) do
        if key~="Bold" and key~="Decoration" and key~="NoShadow" then object[key] = value end
    end
    if (class=="TextLabel" or class=="TextButton" or class=="TextBox") and not (props and props.Decoration) then
        object.TextSize=math.max(9,math.floor((props and props.TextSize or 11)+0.5))
        object.TextStrokeColor3=(props and props.TextStrokeColor3) or Color3.new(0,0,0)
        object.TextStrokeTransparency=(props and props.TextStrokeTransparency) or 1
        local face=Faces[props and props.Bold and "Bold" or "Regular"]
        if face then object.FontFace=face else object.Font=props and props.Bold and Enum.Font.ArialBold or Enum.Font.Arial end
    end
    object.Parent = parent
    if (class=="TextLabel" or class=="TextButton" or class=="TextBox")
        and not (props and (props.Decoration or props.NoShadow)) then addTextShadow(object) end
    return object
end
local function texture(parent,name,props)
    local source=utilityIcon(name) or imageAsset(name)
    if not source then return nil end
    local settings={Image=source,Size=UDim2.fromScale(1,1),BackgroundTransparency=1,BorderSizePixel=0,Active=false}
    for k,v in pairs(props or {}) do settings[k]=v end
    return make("ImageLabel",settings,parent)
end
local function frame(parent, props)
    local defaults = { BackgroundColor3 = C.Panel, BorderSizePixel = 0 }
    for k,v in pairs(props or {}) do defaults[k] = v end
    return make("Frame", defaults, parent)
end
local function label(parent, text, props)
    local defaults = {
        BackgroundTransparency = 1, BorderSizePixel = 0, Text = text,
        Font = Enum.Font.Code, TextSize = 11, TextColor3 = C.Text,
        TextXAlignment = Enum.TextXAlignment.Left, Size = UDim2.new(1,0,0,20),
    }
    for k,v in pairs(props or {}) do defaults[k] = v end
    return make("TextLabel", defaults, parent)
end
local function button(parent, text, props)
    local defaults = {
        BackgroundColor3 = C.Field, BorderSizePixel = 0, AutoButtonColor = false,
        Text = text, Font = Enum.Font.Code, TextSize = 11, TextColor3 = C.Text,
        Size = UDim2.new(1,0,0,22),
    }
    for k,v in pairs(props or {}) do defaults[k] = v end
    return make("TextButton", defaults, parent)
end
local function stroke(object, color)
    return make("UIStroke", { Color = color or C.Border, Thickness = 1,
        ApplyStrokeMode = Enum.ApplyStrokeMode.Border }, object)
end
local function padding(object, n)
    make("UIPadding", {PaddingLeft=UDim.new(0,n), PaddingRight=UDim.new(0,n),
        PaddingTop=UDim.new(0,n), PaddingBottom=UDim.new(0,n)}, object)
end
local function list(object, gap)
    return make("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, gap or 4) }, object)
end
local function finite(value)
    return type(value) == "number" and value == value and math.abs(value) < math.huge
end
local function keycode(name)
    if type(name) ~= "string" then return nil end
    local ok, value = pcall(function() return Enum.KeyCode[name] end)
    if ok and value ~= Enum.KeyCode.Unknown then return value end
    return nil
end
local function primary(input)
    return input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch
end
local function esc(text)
    text=tostring(text)
    text=text:gsub("&","&amp;")
    text=text:gsub("<","&lt;")
    text=text:gsub(">","&gt;")
    return text
end
local function hex(color)
    return string.format("#%02x%02x%02x",math.floor(color.R*255+0.5),math.floor(color.G*255+0.5),math.floor(color.B*255+0.5))
end
-- Tooltip content: a plain string, or {Title=,Path=,Text=,Risky=,TitleColor=} for the rich card.
local function tipText(tip)
    if type(tip)~="table" then return esc(tip) end
    local parts={}
    local head={}
    if tip.Title then table.insert(head,'<font color="'..hex(tip.TitleColor or C.Info)..'">'..esc(tip.Title)..'</font>') end
    if tip.Path then table.insert(head,'<font color="'..hex(C.Muted)..'">'..esc(tip.Path)..'</font>') end
    if #head>0 then table.insert(parts,table.concat(head,"<br/>")) end
    if tip.Text then table.insert(parts,esc(tip.Text)) end
    if tip.Risky then
        table.insert(parts,'<font color="'..hex(C.Risk)..'">risky</font><font color="'..hex(C.Muted)..'"> - '..esc(tip.Risky)..'</font>')
    end
    return table.concat(parts,"<br/><br/>")
end
local KeyShort={LeftShift="LShift",RightShift="RShift",LeftControl="LCtrl",RightControl="RCtrl",LeftAlt="LAlt",RightAlt="RAlt",Backquote="`",Return="Enter"}
local function shortKey(name) return KeyShort[name] or name end

function Window:_connect(signal, callback)
    local connection = signal:Connect(callback)
    table.insert(self.Connections, connection)
    return connection
end
function Window:_call(callback, ...)
    if type(callback) ~= "function" or self.Destroyed then return end
    local args = table.pack(...)
    task.spawn(function()
        if self.Destroyed then return end
        local ok, err = pcall(callback, table.unpack(args, 1, args.n))
        if not ok then warn("[Nocturne callback] " .. tostring(err)) end
    end)
end
function Window:_accent(object, property)
    self.Accents[object] = property
    object[property] = self.Accent
end
function Window:SetAccent(color)
    assert(typeof(color) == "Color3", "SetAccent expects Color3")
    self.Accent = color
    for object, property in pairs(self.Accents) do
        if object.Parent then object[property] = color end
    end
end
function Window:SetStatus(text)
    self.Status.Text = tostring(text)
end
function Window:_cancelTween(object)
    local tween = self.Tweens[object]
    if not tween then return end
    self.Tweens[object] = nil
    pcall(function() tween:Cancel() end)
end
function Window:_tween(object, duration, properties, complete, style, direction)
    self:_cancelTween(object)
    if self.Destroyed then return nil end
    if not self.AnimationsEnabled or not TweenService then
        for property, value in pairs(properties) do object[property] = value end
        if complete then complete() end
        return nil
    end
    local ok, tween = pcall(function()
        local info = TweenInfo.new(
            duration / self.AnimationSpeed,
            style or Enum.EasingStyle.Quint,
            direction or Enum.EasingDirection.Out
        )
        return TweenService:Create(object, info, properties)
    end)
    if not ok or not tween then
        for property, value in pairs(properties) do object[property] = value end
        if complete then complete() end
        return nil
    end
    self.Tweens[object] = tween
    local connection
    connection = tween.Completed:Connect(function(state)
        connection:Disconnect()
        if self.Tweens[object] ~= tween then return end
        self.Tweens[object] = nil
        if complete and state == Enum.PlaybackState.Completed then complete() end
    end)
    tween:Play()
    return tween
end
function Window:_closePicker(instant)
    local picker = self.Picker
    if not picker then return end
    self.Picker = nil
    local close = self.PopupClosers[picker]
    if close then close(instant == true)
    else picker.Visible = false end
end
function Window:SetAnimations(enabled, speed)
    self.AnimationsEnabled = enabled ~= false
    if speed ~= nil then
        assert(finite(speed) and speed > 0, "Animation speed must be a positive number")
        self.AnimationSpeed = speed
    end
end
function Window:SetVisible(visible)
    visible = visible == true
    self.Visible = visible
    self:_closePicker(false)
    self.Tooltip.Visible = false
    if visible then
        self.Main.Visible = true
        self.Main.GroupTransparency = 1
        self:_tween(self.Main, 0.14, {GroupTransparency = 0})
    else
        self.Drag = nil
        self:_cancelCapture()
        self:_tween(self.Main, 0.1, {GroupTransparency = 1}, function()
            if not self.Visible then self.Main.Visible = false end
        end)
    end
end
function Window:Toggle() self:SetVisible(not self.Visible) end
function Window:_cancelCapture()
    if self.Capture then self.Capture.Refresh() end
    self.Capture = nil
end
function Window:Destroy()
    if self.Destroyed then return end
    self.Destroyed = true
    for object, tween in pairs(self.Tweens) do
        self.Tweens[object] = nil
        pcall(function() tween:Cancel() end)
    end
    for _, connection in ipairs(self.Connections) do connection:Disconnect() end
    table.clear(self.Connections)
    self.Gui:Destroy()
    if self.Environment and self.Environment[self.RegistryKey] == self then
        self.Environment[self.RegistryKey] = nil
    end
end
function Window:_dragStart(input, update)
    if not primary(input) then return end
    self.Drag = { Input = input, Update = update }
    update(input.Position)
end
function Window:_tip(target, text, noIcon)
    if not text then return end
    local rich=type(text)=="table"
    local trigger=target
    if not noIcon then
        local info
        if rich then
            -- Rich tips only open from the (i) icon, like a dedicated info button.
            info=button(target,"i",{BackgroundTransparency=1,Size=UDim2.fromOffset(11,11),Position=UDim2.new(1,-12,0.5,-5),TextColor3=C.Muted,TextSize=11})
            trigger=info
        else
            info=label(target,"i",{Size=UDim2.fromOffset(11,11),Position=UDim2.new(1,-12,0.5,-5),TextXAlignment=Enum.TextXAlignment.Center,TextColor3=C.Muted})
        end
        make("UICorner",{CornerRadius=UDim.new(1,0)},info) stroke(info,C.Muted)
    end
    local content=tipText(text)
    self:_connect(trigger.MouseEnter, function()
        self.Tooltip.Text = content
        self.Tooltip.Visible = true
    end)
    self:_connect(trigger.MouseLeave, function() self.Tooltip.Visible = false end)
end
function Window:_register(control, opts)
    if opts.Flag then
        assert(type(opts.Flag) == "string" and not self.Controls[opts.Flag], "Duplicate/invalid Flag: " .. tostring(opts.Flag))
        self.Controls[opts.Flag] = control
    end
    return control
end

function Library:CreateWindow(opts)
    opts = opts or {}
    loadFonts()
    local fontName=selectFont(opts.Font or "Tahoma XP")
    local player = Players.LocalPlayer
    assert(player, "Nocturne must run on the client")
    local self = setmetatable({
        Connections = {}, Accents = {}, Controls = {}, Tabs = {}, Keybinds = {},
        Tweens = {}, PopupClosers = {}, Visible = true,
        FontName = fontName,
        AnimationsEnabled = opts.Animations ~= false,
        AnimationSpeed = math.clamp(opts.AnimationSpeed or 1, 0.1, 10),
        Accent = opts.Accent or C.Accent, ToggleKey = opts.ToggleKey or Enum.KeyCode.RightShift,
        Width = math.clamp(opts.Width or 530, 420, 1400), Height = math.clamp(opts.Height or 620, 320, 1000),
        Gallery = {}, GalleryNext = 1,
        RegistryKey = "__NocturneUI_" .. (opts.Id or "Default"), Destroyed = false,
    }, Window)
    for i, entry in ipairs(opts.ColorGallery or {}) do
        if i > 10 then break end
        local color = typeof(entry) == "Color3" and entry or entry.Color
        local alpha = typeof(entry) == "Color3" and 1 or (entry.Alpha or 1)
        assert(typeof(color) == "Color3" and finite(alpha), "Invalid ColorGallery entry")
        self.Gallery[i] = {Color=color, Alpha=math.clamp(alpha,0,1)}
        self.GalleryNext = i % 10 + 1
    end
    local env = _G
    if type(getgenv) == "function" then
        local ok, result = pcall(getgenv)
        if ok and type(result) == "table" then env = result end
    end
    local previous = env[self.RegistryKey]
    if type(previous) == "table" and type(previous.Destroy) == "function" then previous:Destroy() end
    local gui = make("ScreenGui", {
        Name = "NocturneUI", ResetOnSpawn = false, DisplayOrder = 10000,
        ZIndexBehavior = Enum.ZIndexBehavior.Sibling, IgnoreGuiInset = false,
    })
    self.Gui = gui
    local parents = {}
    if opts.Parent then table.insert(parents, opts.Parent) end
    if type(gethui) == "function" then
        local ok, result = pcall(gethui)
        if ok and typeof(result) == "Instance" then table.insert(parents, result) end
    end
    table.insert(parents, game:GetService("CoreGui"))
    table.insert(parents, player:WaitForChild("PlayerGui"))
    local mounted = false
    for _, parent in ipairs(parents) do
        local ok = pcall(function() gui.Parent = parent end)
        if ok then mounted = true break end
    end
    assert(mounted, "Nocturne: no writable GUI parent")
    self.Environment = env
    pcall(function() env[self.RegistryKey] = self end)
    local root = frame(gui, { Size=UDim2.fromScale(1,1), BackgroundTransparency=1 })
    self.Root = root
    local main = make("CanvasGroup", { Size=UDim2.fromOffset(self.Width,self.Height),
        BackgroundColor3=C.Outer, BorderSizePixel=0, GroupTransparency=0 }, root)
    self.Main = main
    -- Deliberate three-layer frame: dark outer edge, restrained highlight,
    -- then a clean inner separator. This stays even at every window size.
    stroke(main,Color3.fromRGB(7,7,7))
    local bevel=frame(main,{Position=UDim2.fromOffset(1,1),Size=UDim2.new(1,-2,1,-2),BackgroundColor3=C.Outer})
    stroke(bevel,Color3.fromRGB(82,82,82))
    local inner=frame(main,{Position=UDim2.fromOffset(4,4),Size=UDim2.new(1,-8,1,-8),BackgroundColor3=C.Outer})
    stroke(inner,Color3.fromRGB(39,39,39))
    local scale = make("UIScale", {Scale=1}, main)
    self.Scale = scale
    frame(main, {Position=UDim2.fromOffset(5,5), Size=UDim2.new(1,-10,0,1),
        BackgroundColor3=Color3.fromRGB(82,82,82)})
    local dragBar = button(main, "", {Position=UDim2.fromOffset(5,6), Size=UDim2.new(1,-10,0,9), BackgroundTransparency=1})
    self:_tip(dragBar, "Drag to move the window", true)
    self.TabBar = frame(main, {Position=UDim2.fromOffset(16,10), Size=UDim2.new(1,-32,0,21), BackgroundTransparency=1})
    local surface = frame(main, {Position=UDim2.fromOffset(18,42), Size=UDim2.new(1,-36,1,-88), BackgroundColor3=Color3.fromRGB(16,16,16), ClipsDescendants=true})
    stroke(surface)
    local dots = {}
    for i=1,180 do dots[i] = string.rep(". ",210) end
    label(surface, table.concat(dots,"\n"), {Size=UDim2.fromOffset(1500,1500), TextSize=6,
        Decoration=true,TextColor3=Color3.fromRGB(43,43,43), TextYAlignment=Enum.TextYAlignment.Top})
    self.Surface = surface
    local footer = frame(main, {Position=UDim2.new(0,18,1,-39),Size=UDim2.new(1,-36,0,28),BackgroundTransparency=1})
    local badge = label(footer, opts.Avatar and "" or "N", {Size=UDim2.fromOffset(24,24), BackgroundTransparency=0,
        BackgroundColor3=C.Field, TextXAlignment=Enum.TextXAlignment.Center,TextSize=18})
    stroke(badge)
    self:_accent(badge,"TextColor3")
    if opts.Avatar then
        -- Avatar = "headshot" uses the local player's Roblox headshot; any image asset string also works.
        local source = opts.Avatar
        if source == "headshot" then source = "rbxthumb://type=AvatarHeadShot&id="..player.UserId.."&w=60&h=60" end
        make("ImageLabel",{Image=source,Position=UDim2.fromOffset(1,1),Size=UDim2.new(1,-2,1,-2),
            BackgroundTransparency=1,BorderSizePixel=0},badge)
    end
    label(footer, opts.Title or "nocturne / interface", {Bold=true,Position=UDim2.fromOffset(30,-2),Size=UDim2.new(1,-70,0,16),TextSize=11})
    self.Status = label(footer, opts.Subtitle or "ready", {Position=UDim2.fromOffset(30,10),Size=UDim2.new(1,-70,0,14),TextSize=11,TextColor3=C.Muted})
    local grip = button(main, "", {Position=UDim2.new(1,-25,1,-25), Size=UDim2.fromOffset(20,20),BackgroundTransparency=1})
    texture(grip,"resize.png",{Position=UDim2.fromOffset(1,1),Size=UDim2.fromOffset(18,18),ImageColor3=Color3.new(1,1,1)})
    self.Tooltip = label(root,"", {Visible=false,BackgroundTransparency=0,BackgroundColor3=C.Field,
        Size=UDim2.fromOffset(204,0), AutomaticSize=Enum.AutomaticSize.Y, RichText=true,
        TextWrapped=true,TextSize=11,TextYAlignment=Enum.TextYAlignment.Top,ZIndex=100})
    padding(self.Tooltip,6)
    stroke(self.Tooltip)
    -- A small persistent toggle also allows touch-only users to reopen the UI.
    local launcher = button(root,"N",{Position=UDim2.fromOffset(8,8),Size=UDim2.fromOffset(28,28),ZIndex=20})
    self:_accent(launcher,"TextColor3")
    stroke(launcher)
    self:_tip(launcher,"Show / hide Nocturne")
    self:_connect(launcher.Activated,function() self:Toggle() end)
    local function fit(center)
        local size = root.AbsoluteSize
        if size.X < 1 or size.Y < 1 then return end
        scale.Scale = math.min(1, (size.X-16)/self.Width, (size.Y-16)/self.Height)
        local w,h = self.Width*scale.Scale,self.Height*scale.Scale
        local x,y = main.Position.X.Offset,main.Position.Y.Offset
        if center then x,y = (size.X-w)/2,(size.Y-h)/2 end
        main.Position = UDim2.fromOffset(math.clamp(x,0,math.max(0,size.X-w)),math.clamp(y,0,math.max(0,size.Y-h)))
    end
    self:_connect(root:GetPropertyChangedSignal("AbsoluteSize"),function() fit(false) end)
    self:_connect(dragBar.InputBegan,function(input)
        if not primary(input) then return end
        local start, origin = input.Position, main.Position
        self:_dragStart(input,function(point)
            main.Position = UDim2.fromOffset(origin.X.Offset+point.X-start.X,origin.Y.Offset+point.Y-start.Y)
            fit(false)
        end)
    end)
    self:_connect(grip.InputBegan,function(input)
        if not primary(input) then return end
        local start,w,h,s = input.Position,self.Width,self.Height,scale.Scale
        self:_dragStart(input,function(point)
            self.Width = math.clamp(w+(point.X-start.X)/s,420,1400)
            self.Height = math.clamp(h+(point.Y-start.Y)/s,320,1000)
            main.Size = UDim2.fromOffset(self.Width,self.Height)
            fit(false)
        end)
    end)
    self:_connect(UIS.InputChanged,function(input)
        local drag = self.Drag
        if drag and ((drag.Input.UserInputType == Enum.UserInputType.Touch and input == drag.Input)
            or (drag.Input.UserInputType == Enum.UserInputType.MouseButton1 and input.UserInputType == Enum.UserInputType.MouseMovement)) then
            drag.Update(input.Position)
        end
        if self.Tooltip.Visible and input.UserInputType == Enum.UserInputType.MouseMovement then
            local point = Vector2.new(input.Position.X,input.Position.Y)-root.AbsolutePosition
            local size = root.AbsoluteSize
            local tip = self.Tooltip.AbsoluteSize
            self.Tooltip.Position = UDim2.fromOffset(math.clamp(point.X+14,0,math.max(0,size.X-tip.X)),math.clamp(point.Y+18,0,math.max(0,size.Y-tip.Y)))
        end
    end)
    self:_connect(UIS.InputEnded,function(input)
        if self.Drag and (input == self.Drag.Input or (self.Drag.Input.UserInputType == Enum.UserInputType.MouseButton1 and input.UserInputType == Enum.UserInputType.MouseButton1)) then self.Drag=nil end
        for _,bind in ipairs(self.Keybinds) do
            if input.KeyCode == bind.Value then
                if bind.Mode == "Hold" and bind.Active then
                    bind.Active=false self:_call(bind.Callback,false,bind.Value)
                elseif bind.Mode == "OffHold" and not bind.Active then
                    bind.Active=true self:_call(bind.Callback,true,bind.Value)
                end
            end
        end
    end)
    self:_connect(UIS.WindowFocusReleased,function()
        self.Drag=nil
        self:_cancelCapture()
        for _,bind in ipairs(self.Keybinds) do
            if bind.Mode == "Hold" and bind.Active then bind.Active=false self:_call(bind.Callback,false,bind.Value)
            elseif bind.Mode == "OffHold" and not bind.Active then bind.Active=true self:_call(bind.Callback,true,bind.Value) end
        end
    end)
    self:_connect(UIS.InputBegan,function(input, processed)
        if self.Capture then
            if input.UserInputType ~= Enum.UserInputType.Keyboard then return end
            local control = self.Capture
            self.Capture = nil
            if input.KeyCode == Enum.KeyCode.Escape then control.Refresh()
            elseif input.KeyCode == Enum.KeyCode.Backspace then control:Set(nil)
            else control:Set(input.KeyCode) end
            return
        end
        if processed or UIS:GetFocusedTextBox() then return end
        if input.KeyCode == self.ToggleKey then self:Toggle() return end
        for _,bind in ipairs(self.Keybinds) do
            if bind.Mode ~= "Always" and input.KeyCode == bind.Value then
                if bind.Mode == "Toggle" then bind.Active=not bind.Active
                elseif bind.Mode == "Hold" then bind.Active=true
                elseif bind.Mode == "OffHold" then bind.Active=false end
                self:_call(bind.Callback,bind.Mode == "Press" or bind.Active,bind.Value)
            end
        end
    end)
    task.defer(function() if not self.Destroyed then fit(true) end end)
    return self
end

function Window:AddTab(name)
    local tab = setmetatable({Window=self,Name=name,Sections={}},Tab)
    tab.Button = button(self.TabBar,name,{Bold=true,BackgroundTransparency=1,TextSize=11})
    tab.Line = frame(tab.Button,{Position=UDim2.new(0,0,1,-1),Size=UDim2.new(1,0,0,1),BackgroundColor3=Color3.fromRGB(105,105,105)})
    tab.PagePosition = UDim2.fromOffset(6,6)
    tab.PageEnterPosition = UDim2.fromOffset(6,9)
    tab.Page = make("CanvasGroup",{Position=tab.PagePosition,Size=UDim2.new(1,-16,1,-12),
        BackgroundTransparency=1,BorderSizePixel=0,GroupTransparency=0,Visible=false},self.Surface)
    tab.Columns = {}
    for i=1,2 do
        local column = make("ScrollingFrame",{BackgroundTransparency=1,BorderSizePixel=0,
            Position=UDim2.new((i-1)*0.5,0,0,0),Size=UDim2.new(0.5,0,1,0),
            CanvasSize=UDim2.new(),AutomaticCanvasSize=Enum.AutomaticSize.Y,
            ScrollingDirection=Enum.ScrollingDirection.Y,ScrollBarThickness=2,ScrollBarImageColor3=C.Muted,
            ClipsDescendants=true},tab.Page)
        make("UIPadding",{PaddingLeft=UDim.new(0,8),PaddingRight=UDim.new(0,4),
            PaddingTop=UDim.new(0,8),PaddingBottom=UDim.new(0,8)},column)
        list(column,12)
        tab.Columns[i] = column
    end
    table.insert(self.Tabs,tab)
    for i,t in ipairs(self.Tabs) do
        t.Button.Position=UDim2.new((i-1)/#self.Tabs,0,0,0)
        t.Button.Size=UDim2.new(1/#self.Tabs,-6,1,0)
    end
    self:_connect(tab.Button.Activated,function() tab:Select() end)
    if #self.Tabs == 1 then tab:Select() end
    return tab
end
function Tab:Select()
    self.Window:_closePicker(false)
    self.Window.Tooltip.Visible = false
    self.Window:_cancelCapture()
    for _,tab in ipairs(self.Window.Tabs) do
        local active = tab == self
        if active then
            tab.Page.Visible = true
            tab.Page.GroupTransparency = 1
            tab.Page.Position = tab.PageEnterPosition
            self.Window:_tween(tab.Page,0.1,{GroupTransparency=0,Position=tab.PagePosition})
        else
            self.Window:_cancelTween(tab.Page)
            tab.Page.Visible = false
        end
        self.Window:_tween(tab.Button,0.1,{TextColor3=active and C.Text or C.Muted})
        if active then
            self.Window:_tween(tab.Line,0.12,{BackgroundColor3=Color3.fromRGB(130,130,130)})
        else
            self.Window:_tween(tab.Line,0.12,{BackgroundColor3=Color3.fromRGB(105,105,105)})
        end
    end
    self.Window.SelectedTab = self
end
function Tab:AddSection(name, side, minHeight)
    local column = (side == "Right" or side == 2) and 2 or 1
    local panel = frame(self.Columns[column],{Size=UDim2.new(1,0,0,0),AutomaticSize=Enum.AutomaticSize.Y,
        LayoutOrder=#self.Sections+1})
    stroke(panel)
    if minHeight then make("UISizeConstraint",{MinSize=Vector2.new(0,minHeight)},panel) end
    local title = label(panel," "..name.." ",{Bold=true,Position=UDim2.fromOffset(7,-8),Size=UDim2.fromOffset(0,16),
        AutomaticSize=Enum.AutomaticSize.X,BackgroundTransparency=1,TextSize=11,ZIndex=2})
    local content = frame(panel,{Position=UDim2.fromOffset(13,12),Size=UDim2.new(1,-26,0,0),AutomaticSize=Enum.AutomaticSize.Y,BackgroundTransparency=1})
    list(content,0)
    make("UIPadding",{PaddingBottom=UDim.new(0,12)},content)
    local section = setmetatable({Window=self.Window,Frame=panel,Content=content,Title=title,Count=0,Items={}},Section)
    table.insert(self.Sections,section)
    return section
end
function Section:SetTitle(text) self.Title.Text=" "..tostring(text).." " end
function Section:SetVisible(value) self.Frame.Visible=value==true end
-- Greys out (and blocks) every toggle in the section, including its color pickers and key bind.
function Section:SetEnabled(value)
    for _,item in ipairs(self.Items) do
        if item.SetEnabled then item:SetEnabled(value) end
    end
end
function Section:_row(height)
    self.Count=self.Count+1
    return frame(self.Content,{Size=UDim2.new(1,0,0,height or 22),BackgroundTransparency=1,LayoutOrder=self.Count})
end
function Section:AddLabel(text)
    local row=self:_row(32)
    local item=label(row,text,{Size=UDim2.fromScale(1,1),TextWrapped=true,TextSize=11,TextColor3=C.Muted})
    return {Set=function(_,value) item.Text=tostring(value) end,Frame=row}
end
function Section:AddButton(opts)
    local row=self:_row(24)
    local item=button(row,opts.Text or "button")
    local edge=stroke(item)
    self.Window:_connect(item.MouseEnter,function() self.Window:_tween(edge,0.1,{Color=self.Window.Accent}) end)
    self.Window:_connect(item.MouseLeave,function() self.Window:_tween(edge,0.1,{Color=C.Border}) end)
    self.Window:_connect(item.Activated,function() self.Window:_call(opts.Callback) end)
    self.Window:_tip(item,opts.Tooltip)
    return {Frame=row,SetText=function(_,value) item.Text=tostring(value) end}
end
function Section:AddToggle(opts)
    local win,row=self.Window,self:_row(16)
    -- Align accessory swatches with the right edge of the inset fields.
    row.Size=UDim2.new(1,-13,0,16)
    local hit=button(row,"",{Size=UDim2.fromScale(1,1),BackgroundTransparency=1})
    local box=frame(hit,{Position=UDim2.fromOffset(0,4),Size=UDim2.fromOffset(8,8),BackgroundColor3=C.Field})
    stroke(box)
    local fill=frame(box,{Position=UDim2.fromOffset(1,1),Size=UDim2.new(1,-2,1,-2)})
    win:_accent(fill,"BackgroundColor3")
    make("UIGradient",{Color=ColorSequence.new(Color3.new(1,1,1),Color3.fromRGB(100,100,100)),Rotation=90},fill)
    local text=label(hit,opts.Text or "toggle",{Position=UDim2.fromOffset(17,0),Size=UDim2.new(1,-17,1,0),TextSize=11})
    local section=self
    local control={Kind="Toggle",Value=false,Frame=row,Accessories=0,Reserved=0,Hits={},Pickers={},Enabled=true}
    local dim=frame(row,{Size=UDim2.fromScale(1,1),BackgroundColor3=C.Panel,BackgroundTransparency=1,ZIndex=10,Active=false})
    local function relayout()
        local used=control.Reserved+control.Accessories*25
        if used>0 then hit.Size=UDim2.new(1,-(used+4),1,0) end
        dim.Size=hit.Size
    end
    function control:AddColorPicker(options)
        options=table.clone(options or {})
        for _,picker in ipairs(self.Pickers) do
            picker.Position=UDim2.new(1,picker.Position.X.Offset-25,0,0)
        end
        self.Accessories=self.Accessories+1
        options.Row=row options.Slot=1 options.Text=options.Text or opts.Text
        options.Offset=self.Reserved options.Hits=self.Hits options.Pickers=self.Pickers
        options.IsEnabled=function() return control.Enabled end
        relayout()
        return section:AddColorPicker(options)
    end
    -- Compact "[key]" button at the right edge of the row; right click opens the mode menu.
    function control:AddKeybind(options)
        assert(not self.Bind,"Toggle already has a keybind")
        options=table.clone(options or {})
        local width=options.Width or 34
        for _,picker in ipairs(self.Pickers) do
            picker.Position=UDim2.new(1,picker.Position.X.Offset-width,0,0)
        end
        self.Reserved=width
        relayout()
        options.Row=row options.Compact=true options.Width=width options.Offset=0 options.Hits=self.Hits
        options.IsEnabled=function() return control.Enabled end
        options.Text=options.Text or opts.Text
        self.Bind=section:AddKeybind(options)
        return self.Bind
    end
    function control:SetEnabled(value)
        value=value~=false
        self.Enabled=value
        dim.BackgroundTransparency=value and 1 or 0.25
        for _,accessory in ipairs(self.Hits) do accessory.Active=value end
    end
    function control:Validate(value) return type(value)=="boolean" end
    function control:Set(value,silent)
        assert(self:Validate(value),"Toggle expects boolean")
        local changed=self.Value~=value
        self.Value=value
        fill.Visible=true
        local transparency=value and 0 or 1
        local textColor=value and C.On or C.Muted
        if silent or not changed then
            win:_cancelTween(fill) win:_cancelTween(text)
            fill.BackgroundTransparency=transparency text.TextColor3=textColor
        else
            win:_tween(fill,0.1,{BackgroundTransparency=transparency})
            win:_tween(text,0.1,{TextColor3=textColor})
        end
        if changed and not silent then win:_call(opts.Callback,value) end
    end
    function control:Get() return self.Value end
    control:Set(opts.Default==true,true)
    win:_connect(hit.Activated,function() if control.Enabled then control:Set(not control.Value) end end)
    -- Info = {Title=,Path=,Text=,Risky=} draws an (i) icon with a rich tooltip; Tooltip stays a plain string.
    win:_tip(hit,opts.Info or opts.Tooltip)
    table.insert(self.Items,control)
    return win:_register(control,opts)
end
function Section:AddSlider(opts)
    local win,row=self.Window,self:_row(32)
    local min,max,step=opts.Min or 0,opts.Max or 100,opts.Step or 1
    assert(finite(min) and finite(max) and max>min and finite(step) and step>0,"Invalid slider range")
    label(row,opts.Text or "slider",{TextSize=11,Position=UDim2.fromOffset(16,0),Size=UDim2.new(1,-32,0,16)})
    local hit=button(row,"",{Position=UDim2.fromOffset(16,16),Size=UDim2.new(1,-32,0,16),BackgroundTransparency=1})
    local track=frame(hit,{Position=UDim2.fromOffset(0,5),Size=UDim2.new(1,0,0,4),BackgroundColor3=C.Field})
    stroke(track)
    local fill=frame(track,{Size=UDim2.fromScale(0,1)})
    win:_accent(fill,"BackgroundColor3")
    make("UIGradient",{Color=ColorSequence.new(Color3.new(1,1,1),Color3.fromRGB(105,105,105)),Rotation=90},fill)
    -- Slider values intentionally use a real outline instead of the global
    -- offset shadow. This keeps the glyph stable while the TextBox owns focus.
    local valueLabel=label(hit,"",{NoShadow=true,Bold=true,Size=UDim2.fromScale(1,1),TextXAlignment=Enum.TextXAlignment.Center,
        TextSize=11,ZIndex=2,TextStrokeColor3=Color3.new(0,0,0),TextStrokeTransparency=0})
    local less=button(row,"-",{Position=UDim2.fromOffset(0,16),Size=UDim2.fromOffset(16,16),BackgroundTransparency=1,TextColor3=C.Muted})
    local more=button(row,"+",{Position=UDim2.new(1,-16,0,16),Size=UDim2.fromOffset(16,16),BackgroundTransparency=1,TextColor3=C.Muted})
    local edit=make("TextBox",{NoShadow=true,Visible=false,Size=UDim2.fromOffset(64,16),BackgroundTransparency=1,BorderSizePixel=0,
        Text="",TextColor3=C.Text,TextXAlignment=Enum.TextXAlignment.Center,TextSize=11,TextStrokeColor3=Color3.new(0,0,0),
        TextStrokeTransparency=0,ClearTextOnFocus=false,Bold=true,ZIndex=6},hit)
    local valueButton=button(hit,"",{BackgroundTransparency=1,Size=UDim2.fromOffset(52,16),ZIndex=4})
    local control={Kind="Slider",Value=min,Frame=row}
    local errorGeneration=0
    local function invalid()
        errorGeneration=errorGeneration+1
        local generation=errorGeneration
        task.spawn(function()
            local red=Color3.fromRGB(255,75,75)
            for pulse=1,2 do
                for step=0,24 do
                    if win.Destroyed or generation~=errorGeneration then return end
                    local amount=math.sin(math.pi*step/24)^2
                    valueLabel.TextColor3=C.Text:Lerp(red,amount)
                    task.wait(0.02)
                end
            end
            if not win.Destroyed and generation==errorGeneration then valueLabel.TextColor3=C.Text end
        end)
    end
    function control:Validate(value) return finite(value) end
    function control:Set(value,silent,instant)
        assert(self:Validate(value),"Slider expects finite number")
        value=math.clamp(value,min,max)
        if value~=max then value=math.clamp(min+math.floor((value-min)/step+0.5)*step,min,max) end
        value=tonumber(string.format("%.8f",value))
        local changed=self.Value~=value
        self.Value=value
        local fillSize=UDim2.fromScale((value-min)/(max-min),1)
        if silent or instant then
            win:_cancelTween(fill) fill.Size=fillSize
        else
            win:_tween(fill,0.08,{Size=fillSize})
        end
        valueLabel.Text=opts.Format and opts.Format(value) or (tostring(value)..(opts.Suffix or ""))
        local fraction=(value-min)/(max-min)
        valueLabel.AnchorPoint=Vector2.new(fraction,0)
        valueLabel.Size=UDim2.fromOffset(math.max(18,valueLabel.TextBounds.X+4),16)
        valueLabel.Position=UDim2.new(fraction,0,0,0)
        valueButton.AnchorPoint=valueLabel.AnchorPoint
        valueButton.Size=valueLabel.Size
        valueButton.Position=valueLabel.Position
        edit.AnchorPoint=valueLabel.AnchorPoint edit.Position=valueLabel.Position
        if changed and not silent then win:_call(opts.Callback,value) end
    end
    function control:Get() return self.Value end
    control:Set(opts.Default or min,true)
    win:_connect(valueButton.Activated,function()
        win.Drag=nil
        errorGeneration=errorGeneration+1 valueLabel.TextColor3=C.Text
        valueLabel.Visible=false
        edit.Text=tostring(control.Value) edit.Visible=true edit:CaptureFocus()
    end)
    win:_connect(edit.FocusLost,function()
        local number=tonumber(edit.Text)
        edit.Visible=false valueLabel.Visible=true
        if not finite(number) then invalid() return end
        control:Set(number)
    end)
    win:_connect(hit.InputBegan,function(input)
        win:_dragStart(input,function(point)
            control:Set(min+math.clamp((point.X-track.AbsolutePosition.X)/math.max(1,track.AbsoluteSize.X),0,1)*(max-min),false,true)
        end)
    end)
    local heldInput=nil
    local holdGeneration=0
    local function stopHold()
        heldInput=nil
        holdGeneration=holdGeneration+1
        win:_tween(less,0.08,{TextColor3=C.Muted})
        win:_tween(more,0.08,{TextColor3=C.Muted})
    end
    local function beginHold(buttonObject,delta,input)
        if not primary(input) then return end
        stopHold()
        heldInput=input
        local generation=holdGeneration
        win:_tween(buttonObject,0.06,{TextColor3=C.Text})
        control:Set(control.Value+delta)
        task.spawn(function()
            task.wait(0.32)
            while not win.Destroyed and heldInput==input and generation==holdGeneration do
                control:Set(control.Value+delta)
                task.wait(0.06)
            end
        end)
    end
    win:_connect(less.InputBegan,function(input) beginHold(less,-step,input) end)
    win:_connect(more.InputBegan,function(input) beginHold(more,step,input) end)
    win:_connect(UIS.InputEnded,function(input)
        if heldInput and (input==heldInput or input.UserInputType==heldInput.UserInputType) then stopHold() end
    end)
    win:_connect(UIS.WindowFocusReleased,stopHold)
    win:_tip(hit,opts.Tooltip)
    return win:_register(control,opts)
end
function Section:AddDropdown(opts)
    local win,row=self.Window,self:_row(40)
    local values={}
    for _,value in ipairs(opts.Values or {}) do
        assert(type(value)=="string" and not table.find(values,value),"Dropdown values must be unique strings")
        table.insert(values,value)
    end
    assert(#values>0,"Dropdown requires Values")
    local caption=label(row,opts.Text or "select",{TextSize=11,Position=UDim2.fromOffset(16,0),Size=UDim2.new(1,-32,0,16)})
    local selected=button(row,"",{Position=UDim2.fromOffset(16,18),Size=UDim2.new(1,-32,0,18),TextXAlignment=Enum.TextXAlignment.Left,TextSize=11})
    make("UIPadding",{PaddingLeft=UDim.new(0,5),PaddingRight=UDim.new(0,25)},selected)
    stroke(selected)
    local iconName=opts.Icon=="grid" and "grid.png" or "menu.png"
    local dropdownIcon=texture(selected,iconName,{Position=UDim2.new(1,-16,0.5,-6),Size=UDim2.fromOffset(12,12),ImageColor3=Color3.new(1,1,1),ZIndex=3})
    if not dropdownIcon then label(selected,"=",{Size=UDim2.fromScale(1,1),TextXAlignment=Enum.TextXAlignment.Right,TextColor3=C.Muted}) end
    local menu=make("ScrollingFrame",{Visible=false,Position=UDim2.fromOffset(0,43),Size=UDim2.new(1,0,0,0),BackgroundColor3=C.Field,
        BorderSizePixel=0,CanvasSize=UDim2.fromOffset(0,#values*23),ScrollBarThickness=2,ScrollBarImageColor3=C.Muted,ScrollingDirection=Enum.ScrollingDirection.Y},row)
    stroke(menu) list(menu,0)
    menu.Parent=win.Root menu.ZIndex=75
    local control={Kind="Dropdown",Value=nil,Frame=row,Values=values}
    local choices={}
    local menuWidth,menuHeight=0,math.min(6,#values)*23
    local function closeMenu(instant)
        if not menu.Visible then return end
        win:_cancelTween(menu)
        if instant then
            menu.Visible=false
            menu.Size=UDim2.fromOffset(menuWidth,0)
        else
            win:_tween(menu,0.08,{Size=UDim2.fromOffset(menuWidth,0)},function()
                if win.Picker~=menu then menu.Visible=false end
            end)
        end
    end
    win.PopupClosers[menu]=closeMenu
    local function open(value)
        if value then
            win:_closePicker(true)
            win.Picker=menu
            local p=selected.AbsolutePosition-win.Root.AbsolutePosition
            menuWidth=selected.AbsoluteSize.X
            menu.Position=UDim2.fromOffset(math.clamp(p.X,0,math.max(0,win.Root.AbsoluteSize.X-menuWidth)),math.clamp(p.Y+selected.AbsoluteSize.Y+2,0,math.max(0,win.Root.AbsoluteSize.Y-menuHeight)))
            menu.Size=UDim2.fromOffset(menuWidth,0)
            menu.Visible=true
            win:_tween(menu,0.1,{Size=UDim2.fromOffset(menuWidth,menuHeight)})
        else
            if win.Picker==menu then win.Picker=nil end
            closeMenu(false)
        end
    end
    function control:Validate(value) return type(value)=="string" and table.find(values,value)~=nil end
    function control:Set(value,silent)
        assert(self:Validate(value),"Unknown dropdown value: "..tostring(value))
        local changed=self.Value~=value
        self.Value=value selected.Text=value
        for name,item in pairs(choices) do
            if name==value then win:_accent(item,"TextColor3")
            else win.Accents[item]=nil item.TextColor3=C.Muted end
        end
        open(false)
        if changed and not silent then win:_call(opts.Callback,value) end
    end
    function control:Get() return self.Value end
    for i,value in ipairs(values) do
        local item=button(menu,value,{Size=UDim2.new(1,-3,0,23),TextXAlignment=Enum.TextXAlignment.Left,LayoutOrder=i,TextSize=11})
        padding(item,5) choices[value]=item
        win:_connect(item.Activated,function() control:Set(value) end)
    end
    control:Set(opts.Default or values[1],true)
    win:_connect(selected.Activated,function() open(not menu.Visible) end)
    win:_connect(UIS.InputBegan,function(input)
        if not menu.Visible then return end
        if input.KeyCode==Enum.KeyCode.Escape then open(false) return end
        if primary(input) then
            local function inside(obj)
                local p,z=obj.AbsolutePosition,obj.AbsoluteSize
                return input.Position.X>=p.X and input.Position.Y>=p.Y and input.Position.X<=p.X+z.X and input.Position.Y<=p.Y+z.Y
            end
            if not inside(menu) and not inside(selected) then open(false) end
        end
    end)
    win:_tip(caption,opts.Info or opts.Tooltip)
    return win:_register(control,opts)
end
function Section:AddTextbox(opts)
    local win,row=self.Window,self:_row(43)
    label(row,opts.Text or "text",{TextSize=11,Size=UDim2.new(1,0,0,16)})
    local input=make("TextBox",{Position=UDim2.fromOffset(0,18),Size=UDim2.new(1,0,0,21),BackgroundColor3=C.Field,BorderSizePixel=0,
        Text="",PlaceholderText=opts.Placeholder or "...",PlaceholderColor3=C.Muted,TextColor3=C.Text,Font=Enum.Font.Code,TextSize=11,
        TextXAlignment=Enum.TextXAlignment.Left,ClearTextOnFocus=false},row)
    padding(input,4) stroke(input)
    local control={Kind="Textbox",Value="",Frame=row}
    function control:Validate(value) return type(value)=="string" end
    function control:Set(value,silent)
        assert(self:Validate(value),"Textbox expects string")
        -- MaxLength counts Unicode codepoints, preserving UTF-8 text.
        local count=utf8.len(value)
        assert(count,"Textbox expects valid UTF-8")
        local limit=opts.MaxLength or 256
        if count>limit then value=string.sub(value,1,utf8.offset(value,limit+1)-1) end
        local changed=self.Value~=value
        self.Value=value input.Text=value
        if changed and not silent then win:_call(opts.Callback,value) end
    end
    function control:Get() return self.Value end
    control:Set(opts.Default or "",true)
    win:_connect(input.FocusLost,function() control:Set(input.Text) end)
    win:_tip(input,opts.Tooltip)
    return win:_register(control,opts)
end
local BindModes={Hold="on hold",OffHold="off hold",Toggle="toggle",Always="always on"}
local BindOrder={"Hold","OffHold","Toggle","Always"}
local function validMode(mode) return mode=="Press" or BindModes[mode]~=nil end
function Section:AddKeybind(opts)
    local compact=opts.Compact==true and opts.Row~=nil
    local win,row=self.Window,compact and opts.Row or self:_row(24)
    local bindButton
    if compact then
        local width=opts.Width or 44
        bindButton=button(row,"",{Position=UDim2.new(1,-(opts.Offset or 0)-width,0,0),Size=UDim2.fromOffset(width,16),
            BackgroundTransparency=1,TextColor3=C.Muted,TextSize=11,ZIndex=3,TextTruncate=Enum.TextTruncate.AtEnd})
        if opts.Hits then table.insert(opts.Hits,bindButton) end
    else
        label(row,opts.Text or "keybind",{Size=UDim2.new(0.55,0,1,0),TextSize=11})
        bindButton=button(row,"",{Position=UDim2.fromScale(0.55,0),Size=UDim2.new(0.45,0,0,22),TextSize=11})
        stroke(bindButton)
    end
    local control={Kind="Keybind",Value=nil,Mode=opts.Mode or "Press",Active=false,Callback=opts.Callback,Frame=row}
    assert(validMode(control.Mode),"Invalid keybind Mode")
    local refreshModes
    local function resting() return control.Mode=="OffHold" or control.Mode=="Always" end
    function control:Validate(value)
        return value==nil or (typeof(value)=="EnumItem" and value.EnumType==Enum.KeyCode and value~=Enum.KeyCode.Unknown)
    end
    function control.Refresh()
        local name=control.Value and control.Value.Name
        if compact then bindButton.Text="["..(name and shortKey(name) or "none").."]"
        else bindButton.Text=name or "none" end
    end
    function control:Set(value,silent)
        if type(value)=="string" then assert(keycode(value),"Invalid key name") value=keycode(value) end
        assert(self:Validate(value),"Keybind expects Enum.KeyCode or nil")
        local wasActive=self.Active
        self.Active=resting() self.Value=value self.Refresh()
        if not silent then
            if wasActive~=self.Active then win:_call(self.Callback,self.Active,value) end
            win:_call(opts.Changed,value)
        end
    end
    -- Modes: "Press", "Hold" (on hold), "OffHold", "Toggle", "Always" (always on).
    function control:SetMode(mode,silent)
        assert(validMode(mode),"Invalid keybind Mode")
        local changed=self.Mode~=mode
        local wasActive=self.Active
        self.Mode=mode self.Active=resting()
        if refreshModes then refreshModes() end
        if changed and not silent then
            win:_call(opts.ModeChanged,mode)
            if wasActive~=self.Active then win:_call(self.Callback,self.Active,self.Value) end
        end
    end
    function control:Get() return self.Value end
    control:Set(opts.Default,true)
    win:_connect(bindButton.Activated,function()
        if opts.IsEnabled and not opts.IsEnabled() then return end
        win:_cancelCapture() win.Capture=control bindButton.Text="..."
    end)
    if compact then
        local popup=frame(win.Root,{Visible=false,BackgroundColor3=C.Field,ZIndex=90,Size=UDim2.fromOffset(72,18+#BindOrder*14)})
        stroke(popup,Color3.fromRGB(70,70,70))
        label(popup,"mode",{Position=UDim2.fromOffset(0,1),Size=UDim2.new(1,0,0,14),TextSize=10,TextXAlignment=Enum.TextXAlignment.Center,TextColor3=C.Muted,ZIndex=91})
        frame(popup,{Position=UDim2.fromOffset(1,16),Size=UDim2.new(1,-2,0,1),BackgroundColor3=C.Border,ZIndex=91})
        local entries={}
        local function closePopup()
            if win.Picker==popup then win.Picker=nil end
            popup.Visible=false
        end
        for index,mode in ipairs(BindOrder) do
            local item=button(popup,BindModes[mode],{Position=UDim2.fromOffset(0,18+(index-1)*14),Size=UDim2.new(1,0,0,14),
                BackgroundTransparency=1,TextXAlignment=Enum.TextXAlignment.Left,TextSize=11,ZIndex=91})
            make("UIPadding",{PaddingLeft=UDim.new(0,9)},item)
            local bar=frame(item,{Position=UDim2.fromOffset(3,2),Size=UDim2.new(0,2,1,-4),Visible=false,ZIndex=92})
            win:_accent(bar,"BackgroundColor3")
            entries[mode]={Button=item,Bar=bar}
            win:_connect(item.Activated,function() control:SetMode(mode) closePopup() end)
        end
        refreshModes=function()
            for mode,entry in pairs(entries) do
                local selected=control.Mode==mode
                entry.Button.TextColor3=selected and C.Text or C.Muted
                entry.Bar.Visible=selected
            end
        end
        refreshModes()
        win.PopupClosers[popup]=function() popup.Visible=false end
        win:_connect(bindButton.MouseButton2Click,function()
            if opts.IsEnabled and not opts.IsEnabled() then return end
            if popup.Visible then closePopup() return end
            win:_closePicker(true)
            win.Picker=popup
            local p=bindButton.AbsolutePosition-win.Root.AbsolutePosition
            local rootSize=win.Root.AbsoluteSize
            local size=popup.Size
            popup.Position=UDim2.fromOffset(
                math.clamp(p.X+bindButton.AbsoluteSize.X+2,0,math.max(0,rootSize.X-size.X.Offset)),
                math.clamp(p.Y-2,0,math.max(0,rootSize.Y-size.Y.Offset)))
            popup.Visible=true
        end)
        win:_connect(UIS.InputBegan,function(input)
            if not popup.Visible then return end
            if input.KeyCode==Enum.KeyCode.Escape then closePopup() return end
            if primary(input) then
                local p,z=popup.AbsolutePosition,popup.AbsoluteSize
                local inside=input.Position.X>=p.X and input.Position.Y>=p.Y and input.Position.X<=p.X+z.X and input.Position.Y<=p.Y+z.Y
                if not inside then closePopup() end
            end
        end)
        win:_tip(bindButton,opts.Tooltip or "click to bind | right click: mode | Esc: cancel | Backspace: clear",true)
    else
        win:_tip(bindButton,opts.Tooltip or (control.Mode.." | click to bind; Esc: cancel; Backspace: clear"))
    end
    table.insert(win.Keybinds,control)
    return win:_register(control,opts)
end
function Section:AddColorPicker(opts)
    local win,row=self.Window,opts.Row or self:_row(20)
    local hit=button(row,"",{Size=opts.Row and UDim2.fromOffset(23,16) or UDim2.new(1,0,0,20),BackgroundTransparency=1,ZIndex=3})
    if opts.Row then
        hit.Position=UDim2.new(1,-(opts.Offset or 0)-25*(opts.Slot or 1),0,0)
        if opts.Hits then table.insert(opts.Hits,hit) end
        if opts.Pickers then table.insert(opts.Pickers,hit) end
    else label(hit,opts.Text or "color",{Size=UDim2.new(1,-36,1,0)}) end
    local swatch=frame(hit,{Position=UDim2.new(1,-20,0,4),Size=UDim2.fromOffset(18,8)})
    stroke(swatch)
    make("UIGradient",{Rotation=90,Color=ColorSequence.new(Color3.new(1,1,1),Color3.fromRGB(100,100,100))},swatch)

    -- Reference dimensions are logical pixels; the screenshot shows this at 2x.
    local popupWidth,popupHeight=224,256
    local popup=make("CanvasGroup",{Name="NocturneColorbox",Visible=false,Size=UDim2.fromOffset(popupWidth,popupHeight),
        BackgroundColor3=C.Field,BorderSizePixel=0,ZIndex=80,GroupTransparency=1,ClipsDescendants=true},win.Root)
    local popupScale=make("UIScale",{Scale=1},popup)
    stroke(popup,Color3.fromRGB(7,7,7))
    local edge=frame(popup,{Position=UDim2.fromOffset(1,1),Size=UDim2.new(1,-2,1,-2),BackgroundTransparency=1})
    stroke(edge,Color3.fromRGB(65,65,65))
    frame(popup,{Position=UDim2.fromOffset(2,2),Size=UDim2.new(1,-4,0,14),BackgroundColor3=C.Panel})
    label(popup,opts.Text or "color",{Position=UDim2.fromOffset(2,1),Size=UDim2.new(1,-4,0,14),
        TextXAlignment=Enum.TextXAlignment.Center,TextColor3=C.Muted})
    local headerLine=frame(popup,{Position=UDim2.fromOffset(2,16),Size=UDim2.new(1,-4,0,1)})
    win:_accent(headerLine,"BackgroundColor3")

    local sv=button(popup,"",{Name="SaturationValue",Position=UDim2.fromOffset(10,26),Size=UDim2.fromOffset(150,150),BackgroundColor3=Color3.new(1,1,1)})
    stroke(sv)
    local horizontal=make("UIGradient",{},sv)
    local shade=frame(sv,{Size=UDim2.fromScale(1,1),BackgroundColor3=Color3.new(0,0,0),Active=false,ZIndex=2})
    make("UIGradient",{Rotation=90,Transparency=NumberSequence.new(1,0)},shade)
    local cursor=frame(sv,{Size=UDim2.fromOffset(3,3),AnchorPoint=Vector2.new(0.5,0.5),BackgroundColor3=Color3.new(1,1,1),ZIndex=4,Active=false})
    stroke(cursor,Color3.new(0,0,0))
    local hue=button(popup,"",{Name="Hue",Position=UDim2.fromOffset(168,26),Size=UDim2.fromOffset(14,150),BackgroundColor3=Color3.new(1,1,1)})
    local stops={}
    for i=0,6 do table.insert(stops,ColorSequenceKeypoint.new(i/6,Color3.fromHSV(i/6,1,1))) end
    make("UIGradient",{Rotation=90,Color=ColorSequence.new(stops)},hue)
    stroke(hue)
    local hueMark=frame(hue,{Size=UDim2.new(1,2,0,1),Position=UDim2.fromOffset(-1,0),BackgroundColor3=C.Text,ZIndex=3})
    stroke(hueMark,Color3.new(0,0,0))

    local function checker(parent,width,height)
        for y=0,math.ceil(height/7)-1 do for x=0,math.ceil(width/7)-1 do
            frame(parent,{Position=UDim2.fromOffset(x*7,y*7),
                Size=UDim2.fromOffset(math.min(7,width-x*7),math.min(7,height-y*7)),
                BackgroundColor3=(x+y)%2==0 and Color3.fromRGB(145,145,145) or Color3.fromRGB(90,90,90)})
        end end
    end
    local alpha=button(popup,"",{Name="Alpha",Position=UDim2.fromOffset(10,184),Size=UDim2.fromOffset(150,14)})
    checker(alpha,150,14)
    stroke(alpha)
    local alphaColor=frame(alpha,{Size=UDim2.fromScale(1,1),ZIndex=2})
    make("UIGradient",{Transparency=NumberSequence.new(1,0)},alphaColor)
    local alphaMark=frame(alpha,{Size=UDim2.fromOffset(1,14),BackgroundColor3=C.Text,ZIndex=3})
    local previewBase=frame(popup,{Position=UDim2.fromOffset(168,184),Size=UDim2.fromOffset(46,14)})
    checker(previewBase,46,14)
    stroke(previewBase)
    local preview=frame(previewBase,{Size=UDim2.fromScale(1,1),ZIndex=2})

    local inputFrame=frame(popup,{Position=UDim2.fromOffset(10,206),Size=UDim2.fromOffset(204,18),BackgroundColor3=C.Field})
    local inputEdge=stroke(inputFrame)
    local colorInput=make("TextBox",{Name="ColorInput",Position=UDim2.fromOffset(5,0),Size=UDim2.new(1,-29,1,0),
        BackgroundTransparency=1,BorderSizePixel=0,Text="",TextSize=11,TextColor3=C.Text,
        ClearTextOnFocus=false,TextXAlignment=Enum.TextXAlignment.Left},inputFrame)
    local formatButton=button(inputFrame,"Aa",{Position=UDim2.new(1,-24,0,0),Size=UDim2.fromOffset(24,18),
        BackgroundTransparency=1,TextColor3=C.Muted,ZIndex=3})
    local save=button(popup,"save to gallery",{Position=UDim2.fromOffset(10,228),Size=UDim2.fromOffset(204,18),TextColor3=C.Muted})
    stroke(save)
    local control={Kind="ColorPicker",Value=Color3.new(1,1,1),Alpha=math.clamp(opts.Alpha or 1,0,1),Frame=row}
    local h,s,v=0,0,1
    local rgba=opts.Format~="Hex"
    local function paint()
        local color=control.Value
        swatch.BackgroundColor3=color preview.BackgroundColor3=color alphaColor.BackgroundColor3=color
        swatch.BackgroundTransparency=1-control.Alpha preview.BackgroundTransparency=1-control.Alpha
        horizontal.Color=ColorSequence.new(Color3.new(1,1,1),Color3.fromHSV(h,1,1))
        cursor.Position=UDim2.fromScale(s,1-v)
        hueMark.Position=UDim2.new(0,-1,h,-1)
        alphaMark.Position=UDim2.new(control.Alpha,-1,0,0)
        inputEdge.Color=C.Border
        colorInput.Text=rgba and string.format("%d, %d, %d, %d",math.floor(color.R*255+0.5),math.floor(color.G*255+0.5),
            math.floor(color.B*255+0.5),math.floor(control.Alpha*255+0.5))
            or ("#"..color:ToHex()..string.format("%02X",math.floor(control.Alpha*255+0.5)))
    end
    win:_connect(formatButton.Activated,function() rgba=not rgba paint() end)
    function control:Validate(value) return typeof(value)=="Color3" end
    function control:Set(value,silent)
        assert(self:Validate(value),"ColorPicker expects Color3")
        local changed=self.Value~=value
        self.Value=value h,s,v=value:ToHSV() paint()
        if changed and not silent then win:_call(opts.Callback,value,self.Alpha) end
    end
    function control:SetAlpha(value,silent)
        assert(finite(value),"Alpha expects a finite number")
        value=math.clamp(value,0,1)
        local changed=self.Alpha~=value self.Alpha=value paint()
        if changed and not silent then win:_call(opts.Callback,self.Value,value) end
    end
    function control:Get() return self.Value end
    function control:GetAlpha() return self.Alpha end
    function control.Notify() win:_call(opts.Callback,control.Value,control.Alpha) end
    local function update()
        local color=Color3.fromHSV(h,s,v)
        local changed=control.Value~=color control.Value=color paint()
        if changed then control.Notify() end
    end
    local function drag(input,updateDrag)
        if opts.IsEnabled and not opts.IsEnabled() then return end
        win:_dragStart(input,updateDrag)
        if primary(input) and win.Drag then win.Drag.Owner=popup end
    end
    win:_connect(sv.InputBegan,function(input) drag(input,function(p)
        s=math.clamp((p.X-sv.AbsolutePosition.X)/math.max(1,sv.AbsoluteSize.X),0,1)
        v=1-math.clamp((p.Y-sv.AbsolutePosition.Y)/math.max(1,sv.AbsoluteSize.Y),0,1) update()
    end) end)
    win:_connect(hue.InputBegan,function(input) drag(input,function(p)
        h=math.clamp((p.Y-hue.AbsolutePosition.Y)/math.max(1,hue.AbsoluteSize.Y),0,1) update()
    end) end)
    win:_connect(alpha.InputBegan,function(input) drag(input,function(p)
        control:SetAlpha((p.X-alpha.AbsolutePosition.X)/math.max(1,alpha.AbsoluteSize.X))
    end) end)
    win:_connect(colorInput.FocusLost,function()
        local text=colorInput.Text:gsub("^#",""):gsub("%s","")
        local r,g,b,a=text:match("^(%d+),(%d+),(%d+),(%d+)$")
        local color,newAlpha
        if r then
            r,g,b,a=tonumber(r),tonumber(g),tonumber(b),tonumber(a)
            if r<=255 and g<=255 and b<=255 and a<=255 then
                color,newAlpha=Color3.fromRGB(r,g,b),a/255
            end
        elseif (#text==6 or #text==8) and text:match("^%x+$") then
            color=Color3.fromRGB(tonumber(text:sub(1,2),16),tonumber(text:sub(3,4),16),tonumber(text:sub(5,6),16))
            newAlpha=#text==8 and tonumber(text:sub(7,8),16)/255 or control.Alpha
        end
        if color then
            local changed=control.Value~=color or control.Alpha~=newAlpha
            control.Alpha=newAlpha control:Set(color,true)
            if changed then control.Notify() end
        else
            paint()
            inputEdge.Color=C.Risk
        end
    end)

    local gallery={}
    local function refreshGallery()
        for i,entry in ipairs(gallery) do
            local saved=win.Gallery[i]
            entry.Button.BackgroundColor3=saved and saved.Color or C.Field
            entry.Button.BackgroundTransparency=saved and 1-saved.Alpha or 0
            entry.Gradient.Enabled=saved~=nil
        end
    end
    for i=1,10 do
        local item=button(popup,"",{Name="Gallery"..i,Position=UDim2.fromOffset(190,26+(i-1)*15),
            Size=UDim2.fromOffset(22,11),BackgroundColor3=C.Field})
        stroke(item)
        local gradient=make("UIGradient",{Enabled=false,Rotation=90,
            Color=ColorSequence.new(Color3.new(1,1,1),Color3.fromRGB(100,100,100))},item)
        gallery[i]={Button=item,Gradient=gradient}
        win:_connect(item.Activated,function()
            local entry=win.Gallery[i]
            if entry then
                local changed=control.Value~=entry.Color or control.Alpha~=entry.Alpha
                control.Alpha=entry.Alpha control:Set(entry.Color,true)
                if changed then control.Notify() end
            end
        end)
    end
    win:_connect(save.Activated,function()
        win.Gallery[win.GalleryNext]={Color=control.Value,Alpha=control.Alpha}
        win.GalleryNext=win.GalleryNext%10+1
        refreshGallery()
    end)
    local function inside(point,obj)
        local p,z=obj.AbsolutePosition,obj.AbsoluteSize
        return point.X>=p.X and point.Y>=p.Y and point.X<=p.X+z.X and point.Y<=p.Y+z.Y
    end
    local function closePopup(instant)
        if win.Drag and win.Drag.Owner==popup then win.Drag=nil end
        if not popup.Visible then return end
        win:_cancelTween(popup)
        if instant then
            popup.Visible=false popup.GroupTransparency=1
        else
            win:_tween(popup,0.08,{GroupTransparency=1},function()
                if win.Picker~=popup then popup.Visible=false end
            end)
        end
    end
    win.PopupClosers[popup]=closePopup
    win:_connect(UIS.InputBegan,function(input)
        if popup.Visible and ((primary(input) and not inside(input.Position,popup) and not inside(input.Position,hit)) or input.KeyCode==Enum.KeyCode.Escape) then
            if win.Picker==popup then win:_closePicker(false) else closePopup(false) end
        end
    end)
    win:_connect(hit.Activated,function()
        if opts.IsEnabled and not opts.IsEnabled() then return end
        local show=win.Picker~=popup or not popup.Visible
        if not show then win:_closePicker(false) return end
        win:_closePicker(true)
        win.Tooltip.Visible=false
        win.Picker=popup
        local p=hit.AbsolutePosition-win.Root.AbsolutePosition local size=win.Root.AbsoluteSize
        local scale=math.max(0.1,math.min(win.Scale.Scale,(size.X-8)/popupWidth,(size.Y-8)/popupHeight))
        popupScale.Scale=scale
        local width,height=popupWidth*scale,popupHeight*scale
        local x=p.X+hit.AbsoluteSize.X+6
        if x+width>size.X-4 then x=p.X-width-6 end
        popup.Position=UDim2.fromOffset(math.clamp(x,0,math.max(0,size.X-width)),math.clamp(p.Y,0,math.max(0,size.Y-height)))
        refreshGallery()
        paint()
        popup.GroupTransparency=1
        popup.Visible=true
        win:_tween(popup,0.1,{GroupTransparency=0})
    end)
    control:Set(opts.Default or C.Accent,true)
    return win:_register(control,opts)
end

function Window:GetValues()
    local values={}
    for flag,control in pairs(self.Controls) do values[flag]=control:Get() end
    return values
end
function Window:ExportConfig()
    local values={}
    for flag,control in pairs(self.Controls) do
        local value=control:Get()
        if control.Kind=="ColorPicker" then value={value.R,value.G,value.B}
        elseif control.Kind=="Keybind" then value=value and value.Name or false end
        values[flag]={Kind=control.Kind,Value=value,Alpha=control.Alpha,Mode=control.Kind=="Keybind" and control.Mode or nil}
    end
    return Http:JSONEncode({Version=1,Values=values})
end
function Window:ImportConfig(json, silent)
    local ok,data=pcall(function() return Http:JSONDecode(json) end)
    if not ok or type(data)~="table" or data.Version~=1 or type(data.Values)~="table" then return false,"Invalid Nocturne config" end
    local pending={}
    for flag,entry in pairs(data.Values) do
        local control=self.Controls[flag]
        if control then
            if type(entry)~="table" or entry.Kind~=control.Kind then return false,"Wrong type: "..flag end
            local value=entry.Value
            if control.Kind=="ColorPicker" and entry.Alpha~=nil and (not finite(entry.Alpha) or entry.Alpha<0 or entry.Alpha>1) then return false,"Invalid alpha: "..flag end
            if control.Kind=="ColorPicker" then
                if type(value)~="table" or #value~=3 then return false,"Invalid color: "..flag end
                for _,channel in ipairs(value) do if not finite(channel) or channel<0 or channel>1 then return false,"Invalid color: "..flag end end
                value=Color3.new(value[1],value[2],value[3])
            elseif control.Kind=="Keybind" then
                if value==false then value=nil
                else value=keycode(value) if not value then return false,"Invalid key: "..flag end end
            end
            if not control:Validate(value) then return false,"Invalid value: "..flag end
            if control.Kind=="Textbox" and not utf8.len(value) then return false,"Invalid UTF-8: "..flag end
            table.insert(pending,{Control=control,Value=value,Alpha=entry.Alpha,Mode=entry.Mode})
        end
    end
    for _,change in ipairs(pending) do
        if change.Control.Kind=="ColorPicker" then change.Control.Alpha=change.Alpha or 1 end
        local old=change.Control.Value
        if change.Control.Kind=="Keybind" and type(change.Mode)=="string" and validMode(change.Mode) then
            change.Control:SetMode(change.Mode,silent~=false)
        end
        change.Control:Set(change.Value,silent~=false)
        if change.Control.Kind=="ColorPicker" and silent==false and old==change.Value and change.Alpha~=nil then
            if change.Control.Notify then change.Control.Notify() end
        end
    end
    return true
end
local function configPath(name)
    assert(type(name)=="string" and #name>0 and #name<=64 and name:match("^[%w_-]+$"),"Use a config name with letters, numbers, _ or -")
    return "Nocturne_"..name..".json"
end
function Window:SaveConfig(name)
    if type(writefile)~="function" then return false,"Executor does not provide writefile" end
    return pcall(function() writefile(configPath(name),self:ExportConfig()) end)
end
function Window:LoadConfig(name, silent)
    if type(readfile)~="function" then return false,"Executor does not provide readfile" end
    local ok,result=pcall(function() return readfile(configPath(name)) end)
    if not ok then return false,tostring(result) end
    return self:ImportConfig(result,silent)
end
function Tab:AddSubTab(name, icon)
    icon=icon or builtinIcon(name)
    if not self.SubBar then
        self.SubTabs={}
        self.SubBar=frame(self.Page,{Size=UDim2.new(1,0,0,56)}) stroke(self.SubBar)
        for _,column in ipairs(self.Columns) do column.Visible=false end
    end
    local sub=setmetatable({Window=self.Window,Name=name,Index=#self.SubTabs+1,Sections={},Columns={}},Tab)
    sub.PagePosition=UDim2.fromOffset(0,70)
    sub.Page=make("CanvasGroup",{Position=sub.PagePosition,Size=UDim2.new(1,0,1,-70),
        BackgroundTransparency=1,BorderSizePixel=0,GroupTransparency=0,Visible=false},self.Page)
    sub.Button=button(self.SubBar,name,{BackgroundTransparency=1})
    if not icon then
        sub.Button.Text=""
        local glyph=frame(sub.Button,{Size=UDim2.fromOffset(24,24),Position=UDim2.new(0.5,-12,0,6),BackgroundTransparency=1})
        sub.Glyph=glyph
        local function line(x1,y1,x2,y2)
            local dx,dy=x2-x1,y2-y1
            frame(glyph,{Position=UDim2.fromOffset((x1+x2)/2,(y1+y2)/2),AnchorPoint=Vector2.new(0.5,0.5),Size=UDim2.fromOffset(math.sqrt(dx*dx+dy*dy),1.5),Rotation=math.deg(math.atan2(dy,dx)),BackgroundColor3=C.Muted})
        end
        local function oval(x,y,w,h)
            local f=frame(glyph,{Position=UDim2.fromOffset(x,y),Size=UDim2.fromOffset(w,h),BackgroundTransparency=1})
            make("UICorner",{CornerRadius=UDim.new(1,0)},f) stroke(f,C.Muted)
        end
        if name=="animals" then
            oval(7,11,10,10) oval(2,7,4,5) oval(6,1,4,6) oval(13,1,4,6) oval(18,7,4,5)
        elseif name=="world" then
            oval(2,2,20,20) oval(8,2,8,20) line(2,12,22,12) line(5,6,19,6) line(5,18,19,18)
        elseif name=="local" then
            line(1,12,6,6) line(6,6,18,6) line(18,6,23,12) line(23,12,18,18) line(18,18,6,18) line(6,18,1,12) oval(8,8,8,8)
        else
            oval(4,2,8,8) oval(14,3,6,6) line(1,21,2,16) line(2,16,7,12) line(7,12,12,13) line(12,13,16,18) line(16,18,16,21) line(17,12,22,16) line(22,16,23,21)
        end
        sub.Caption=label(sub.Button,name,{Position=UDim2.new(0,0,1,-20),Size=UDim2.new(1,0,0,18),TextXAlignment=Enum.TextXAlignment.Center})
    end
    if icon then
        sub.Icon=make("ImageLabel",{Image=icon,BackgroundTransparency=1,Size=UDim2.fromOffset(22,22),Position=UDim2.new(0.5,-11,0,7),ImageColor3=C.Muted},sub.Button)
        sub.Button.Text=""
        sub.Caption=label(sub.Button,name,{Position=UDim2.new(0,0,1,-20),Size=UDim2.new(1,0,0,18),TextXAlignment=Enum.TextXAlignment.Center})
    end
    -- The indicator belongs to the icon, not to the caption below it.
    sub.Line=frame(sub.Button,{AnchorPoint=Vector2.new(0.5,0),Position=UDim2.new(0.5,0,0,32),Size=UDim2.fromOffset(24,1)})
    self.Window:_accent(sub.Line,"BackgroundColor3")
    sub.Line.Visible=false
    sub.Caption.TextColor3=C.Muted
    for i=1,2 do
        local col=make("ScrollingFrame",{Position=UDim2.new((i-1)*0.5,0,0,0),Size=UDim2.new(0.5,0,1,0),
            BackgroundTransparency=1,BorderSizePixel=0,CanvasSize=UDim2.new(),AutomaticCanvasSize=Enum.AutomaticSize.Y,
            ScrollBarThickness=2,ScrollBarImageColor3=C.Muted,ScrollingDirection=Enum.ScrollingDirection.Y},sub.Page)
        make("UIPadding",{PaddingLeft=UDim.new(0,8),PaddingRight=UDim.new(0,4),
            PaddingTop=UDim.new(0,8),PaddingBottom=UDim.new(0,8)},col)
        list(col,12) sub.Columns[i]=col
    end
    local owner=self
    function sub:Select()
        self.Window:_closePicker(false)
        self.Window:_cancelCapture()
        local previous=owner.SelectedSubTab
        if previous==self then return end
        local direction=previous and (self.Index>previous.Index and 1 or -1) or 1
        owner.SelectedSubTab=self
        for _,other in ipairs(owner.SubTabs) do
            local active=other==self
            if active then
                self.Window:_cancelTween(other.Page)
                other.Page.Visible=true
                other.Page.GroupTransparency=1
                other.Page.Position=UDim2.fromOffset(direction*24,70)
                self.Window:_tween(other.Page,0.12,{GroupTransparency=0,Position=other.PagePosition})
                other.Line.Visible=true
                other.Line.Size=UDim2.fromOffset(0,1)
                other.Line.BackgroundTransparency=1
                self.Window:_tween(other.Line,0.12,{Size=UDim2.fromOffset(24,1),BackgroundTransparency=0})
            else
                if other.Page.Visible then
                    self.Window:_tween(other.Page,0.1,{GroupTransparency=1,Position=UDim2.fromOffset(-direction*24,70)},function()
                        if owner.SelectedSubTab~=other then other.Page.Visible=false end
                    end)
                end
                if other.Line.Visible then
                    self.Window:_tween(other.Line,0.08,{Size=UDim2.fromOffset(0,1),BackgroundTransparency=1},function()
                        if owner.SelectedSubTab~=other then other.Line.Visible=false end
                    end)
                end
            end
            local function tint(object,property)
                local color
                if active then
                    self.Window.Accents[object]=property
                    color=self.Window.Accent
                else
                    self.Window.Accents[object]=nil
                    color=C.Muted
                end
                self.Window:_tween(object,0.12,{[property]=color})
            end
            tint(other.Caption,"TextColor3")
            if other.Icon then
                local color=active and self.Window.Accent or C.Muted
                if active then self.Window.Accents[other.Icon]="ImageColor3" else self.Window.Accents[other.Icon]=nil end
                self.Window:_tween(other.Icon,0.12,{
                    ImageColor3=color,
                    Position=active and UDim2.new(0.5,-12,0,5) or UDim2.new(0.5,-11,0,7),
                    Size=active and UDim2.fromOffset(24,24) or UDim2.fromOffset(22,22),
                })
            end
            if other.Glyph then
                self.Window:_tween(other.Glyph,0.12,{Position=active and UDim2.new(0.5,-12,0,4) or UDim2.new(0.5,-12,0,6)})
                for _,part in ipairs(other.Glyph:GetDescendants()) do
                    if part:IsA("UIStroke") then tint(part,"Color")
                    elseif part:IsA("Frame") and part.BackgroundTransparency==0 then tint(part,"BackgroundColor3") end
                end
            end
        end
    end
    table.insert(self.SubTabs,sub)
    for i,item in ipairs(self.SubTabs) do
        item.Button.Position=UDim2.new((i-1)/#self.SubTabs,0,0,0)
        item.Button.Size=UDim2.new(1/#self.SubTabs,0,1,0)
    end
    self.Window:_connect(sub.Button.Activated,function() sub:Select() end)
    if #self.SubTabs==1 then sub:Select() end
    return sub
end
function Section:AddListbox(opts)
    local win=self.Window
    local values=table.clone(opts.Values or {})
    assert(#values>0,"Listbox requires Values")
    local row=self:_row(opts.Height or 240)
    local scroll=make("ScrollingFrame",{Size=UDim2.fromScale(1,1),BackgroundColor3=C.Field,BorderSizePixel=0,
        CanvasSize=UDim2.fromOffset(0,#values*18),ScrollBarThickness=2,ScrollBarImageColor3=C.Muted,ScrollingDirection=Enum.ScrollingDirection.Y},row)
    stroke(scroll) list(scroll,0)
    local control={Kind="Listbox",Frame=row,Value=nil}
    local items={}
    function control:Validate(value) return type(value)=="string" and table.find(values,value)~=nil end
    function control:Get() return self.Value end
    function control:Set(value,silent)
        assert(self:Validate(value),"Unknown listbox value")
        local changed=self.Value~=value self.Value=value
        for name,item in pairs(items) do
            item.Button.BackgroundColor3=name==value and Color3.fromRGB(35,35,35) or C.Field
            item.Line.Visible=name==value item.Button.TextColor3=name==value and C.Text or C.Muted
        end
        if changed and not silent then win:_call(opts.Callback,value) end
    end
    for i,value in ipairs(values) do
        assert(type(value)=="string" and not items[value],"Listbox values must be unique strings")
        local item=button(scroll,value,{Size=UDim2.new(1,-4,0,18),LayoutOrder=i,TextXAlignment=Enum.TextXAlignment.Left,Bold=true})
        local line=frame(item,{Size=UDim2.fromOffset(2,18)}) win:_accent(line,"BackgroundColor3")
        make("UIPadding",{PaddingLeft=UDim.new(0,5)},item)
        frame(item,{Position=UDim2.new(1,-8,0,4),Size=UDim2.fromOffset(3,10),BackgroundColor3=opts.StatusColor or Color3.fromRGB(157,101,108)})
        items[value]={Button=item,Line=line}
        win:_connect(item.Activated,function() control:Set(value) end)
    end
    control:Set(opts.Default or values[1],true)
    return win:_register(control,opts)
end

return Library


end)()

local Player = game:GetService("Players").LocalPlayer
local ROLE = "fallen"

local Window = Library:CreateWindow({
    Id = "Demo",
    Title = Player.Name,        -- bold name in the footer
    Subtitle = ROLE,            -- grey line under the name
    Avatar = "headshot",        -- avatar in the footer (or any rbxassetid / rbxthumb string)
    Width = 530,
    Height = 620,
    Animations = true,
    AnimationSpeed = 1,
    Font = "Tahoma XP",
    ColorGallery = { Color3.fromRGB(255, 0, 0), Color3.fromRGB(103, 187, 117) },
})

-- Callbacks: put your own logic here. It stays silent so the footer keeps showing the role.
local function report(value) end

-- Temporary status text in the footer (used by the config buttons).
local function notify(text)
    Window:SetStatus(text)
    task.delay(2, function()
        if not Window.Destroyed then Window:SetStatus(ROLE) end
    end)
end

-- Rich tooltip shown from the (i) icon.
local function info(title, path, text, risky)
    return { Title = title, Path = path, Text = text, Risky = risky }
end

-- toggle(section, text, flag, color, {On=, Info=, Callback=})
local function toggle(section, text, flag, color, extra)
    extra = extra or {}
    local item = section:AddToggle({
        Text = text,
        Flag = flag,
        Default = extra.On,
        Info = extra.Info,
        Callback = extra.Callback or report,
    })
    if color then item:AddColorPicker({ Default = color, Flag = flag .. "Color", Callback = report }) end
    return item
end

